import 'dart:async';
import 'dart:convert';
import 'package:consolecrypt/core/bridge/rust_agent_metrics_collector.dart';
import 'package:consolecrypt/monitoring/agent_association_models.dart';
import 'package:consolecrypt/monitoring/agent_metrics_collector_controller.dart';
import 'package:consolecrypt/monitoring/agent_metrics_collector_models.dart';
import 'package:consolecrypt/monitoring/agent_metrics_collector_wire.dart';
import 'package:consolecrypt/src/rust/api/agent_collector.dart' as native;
import 'package:flutter_test/flutter_test.dart';
import '../support/agent_metrics_fixture.dart' as f;

void main(){
  AgentMetricsCollectorView parse(Map<String,dynamic> v)=>parseAgentMetricsCollectorView(jsonEncode(v),f.scope,AgentMetricsCollectorIntent(f.metricRecord(),300));
  test('closed volatile review preserves exact original and disclaims durable delivery',(){final v=parse(f.view());expect(v.hostRevision,'9007199254740993');expect(v.actorAdmission,isFalse);expect(v.automaticRenewal,isFalse);expect(v.crashReplay,isFalse);expect(v.deliveryGuaranteed,isFalse);expect(v.collector.manifest.receiverUrl,'http://127.0.0.1:9090/api/v1/write');});
  test('only actual running ACK shape carries lease and admission',(){final running=parse(f.view(phase:'running'));expect(running.actorAdmission,isTrue);expect(running.leaseHash,'c'*64);for(final bad in[f.view()..['actorAdmission']=true,f.view(phase:'running')..remove('leaseHash'),f.view()..['command']='run',f.view()..['deliveryGuaranteed']=true]){expect(()=>parse(bad),throwsFormatException);}});
  test('foreign frame saved revision node and receiver metadata refuse',(){for(final key in['profileId','notificationScopeId','associationId','hostRevision']){final v=f.view()..[key]='foreign';expect(()=>parse(v),throwsFormatException);}final node=f.view();(node['node']as Map)['keyEpoch']='2';expect(()=>parse(node),throwsFormatException);});
  test('duration and separate Metrics identity checked before any prepare',(){expect(()=>AgentMetricsCollectorIntent(f.metricRecord(),301),throwsFormatException);final r=f.metricRecord();final tunnel=AgentAssociationRecord(associationId:r.id,hostId:r.hostId,agentId:r.agentId,phase:r.phase,hostRevision:r.hostRevision,nodeKeyFingerprint:r.nodeKeyFingerprint,certificateDigest:r.certificateDigest,nodeKeyEpoch:r.nodeKeyEpoch,purpose:AgentAssociationPurpose.tunnel);expect(()=>AgentMetricsCollectorIntent(tunnel,300),throwsFormatException);});
  test('cleanup Unknown never claims stopped or delivered',(){final v=parseAgentMetricsCollectorCleanup(f.cleanup(state:'unknown'));expect(v.state,AgentMetricsCleanupState.unknown);expect(v.deliveryGuaranteed,isFalse);expect(()=>parseAgentMetricsCollectorCleanup(f.cleanup(phase:'stopped')),throwsFormatException);});
  test('construction is lazy and fixed prepare contains no URLs or authority',()async{final h=f.NativeHandle(),calls=f.Calls(f.NativeHandle());calls.current=h;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>true,now:()=>f.now);expect(calls.requests,isEmpty);await c.prepare();expect(calls.requests.single,{'version':1,'profileId':f.scope.profileId,'notificationScopeId':f.scope.nonce,'associationId':f.metricRecord().id,'durationSeconds':300});expect(h.calls,['details']);await c.close();c.dispose();});
  test('one approval uses same handle and stop request is not stopped',()async{final h=f.NativeHandle(),calls=f.Calls(f.NativeHandle());calls.current=h;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>true,now:()=>f.now);await c.prepare();await c.approveOnce();await c.approveOnce();expect(h.calls.where((x)=>x=='approve').length,1);await c.stop();expect(c.view!.phase,AgentMetricsCollectorPhase.running);expect(c.stopSpent,isTrue);await c.stop();expect(h.calls.where((x)=>x=='stop').length,1);await c.close();c.dispose();});
  test('late prepare ACK after owner retirement cancels joins and disposes original',()async{final h=f.NativeHandle(),calls=f.Calls(f.NativeHandle())..pending=Completer<native.AgentCollectorHandle>();bool current=true;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>current,now:()=>f.now);final preparing=c.prepare();current=false;c.retire();final closing=c.close();calls.pending!.complete(h);await preparing;await closing;expect(h.calls,['cancel','joined','dispose']);expect(c.view,isNull);expect(calls.requests.length,1);c.dispose();});
  test('cancel retains original cleanup future until actual join observation',()async{final h=f.NativeHandle()..pendingJoin=Completer<String>(),calls=f.Calls(f.NativeHandle());calls.current=h;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>true,now:()=>f.now);await c.prepare();c.cancel();final closing=c.close();await Future<void>.delayed(Duration.zero);expect(c.awaitingCleanup,isTrue);expect(h.calls, isNot(contains('dispose')));h.pendingJoin!.complete(f.cleanup(state:'unknown'));await closing;expect(c.unknown,isTrue);expect(h.calls.where((x)=>x=='cancel').length,1);expect(h.calls.last,'dispose');c.dispose();});
  test('refresh cannot extend original review or session budgets',()async{var elapsed=Duration.zero;final h=f.NativeHandle(),calls=f.Calls(f.NativeHandle());calls.current=h;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>true,elapsed:()=>elapsed,now:()=>f.now);await c.prepare();elapsed=const Duration(seconds:30);await c.refresh();expect(c.reviewRemainingMs,30000);expect(c.sessionRemainingMs,270000);await c.close();c.dispose();});
  test('approval pending at review expiry cannot adopt late ACK',()async{var elapsed=Duration.zero;final h=f.NativeHandle()..pendingApprove=Completer<String>(),calls=f.Calls(f.NativeHandle());calls.current=h;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>true,elapsed:()=>elapsed,now:()=>f.now);await c.prepare();final approval=c.approveOnce();elapsed=const Duration(seconds:61);await Future<void>.delayed(const Duration(milliseconds:1050));expect(c.expired,isTrue);h.pendingApprove!.complete(jsonEncode(f.view(phase:'running')));await approval;await c.close();expect(c.view!.actorAdmission,isFalse);expect(h.calls,contains('cancel'));c.dispose();});
  test('foreign catalog on explicit refresh retires same original without retry',()async{final h=f.NativeHandle(),calls=f.Calls(f.NativeHandle());calls.current=h;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>true,now:()=>f.now);await c.prepare();h.detailsReply=jsonEncode(f.view()..['manifestSha256']='a'*64);await c.refresh();await c.close();expect(c.unknown,isTrue);expect(calls.requests.length,1);expect(h.calls,contains('cancel'));c.dispose();});
  test('explicit cleanup observation neither cancels nor disposes running session',()async{final h=f.NativeHandle()..joinedReply=f.cleanup(state:'unknown',phase:'running',admitted:true),calls=f.Calls(f.NativeHandle());calls.current=h;final c=AgentMetricsCollectorController(port:RustAgentMetricsCollectorPort(calls:calls),scope:f.scope,record:f.metricRecord(),original:()=>true,now:()=>f.now);await c.prepare();await c.approveOnce();await c.observeCleanup();expect(c.unknown,isTrue);expect(h.calls,isNot(contains('cancel')));expect(h.calls,isNot(contains('dispose')));await c.close();c.dispose();});
}
